"""
K8s information provider

This module provides the functionality to collect by component the information from the k8s cluster.

The information is collected by ssh to the master node and executing kubectl commands.

There are two types of components:
- CPNRT, CPNB, UPUE: The component is deployed as a pod on the VCU
- CPRT: The component is deployed as a pod on a VDU

The information is collected by the following steps:
- Get the namespace for the component
- Get the pod names for the component
- Get the container names for the component
"""

from taf.collectors.core.entities import managed_ssh_connection
from contextlib import contextmanager
import functools
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def cache_execution_results(func):
    """
    Caches the return values of a function. If the function is called with
    the same arguments again, the cached value is returned.
    """
    cache = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (func.__name__, args, frozenset(kwargs.items()))
        if key in cache:
            return cache[key]
        else:
            result = func(*args, **kwargs)
            cache[key] = result
            return result
    return wrapper


class K8sInformationProvider:
    """
    Collects information from a remote host via SSH
    """

    def __init__(self, tl_config_information_provider):
        """
        Constructor.

        :param TestlineConfigurationInformationProvider tl_config_information_provider:
            Testline configuration information provider.
        """
        self._tl_config_information_provider = tl_config_information_provider
        self._cloud_information = None

    @contextmanager
    def master_node_connection(self, gnb_id, du_id=None):
        """
        Context manager for a SSH connection to the master node.

        :param str component: Component
        :param int gnb_id: Node ID
        :param int du_id: VDU ID
        :return: SSH connection
        """
        if du_id is None:
            ssh_connection_details = self._tl_config_information_provider.get_cu_master_node_ssh_details(gnb_id)
        else:
            ssh_connection_details = self._tl_config_information_provider.get_vdu_master_node_ssh_details(gnb_id, du_id)

        ssh_connection = managed_ssh_connection.ManagedSshConnection(
            host=ssh_connection_details.addr,
                user=ssh_connection_details.username,
                password=ssh_connection_details.password)
        ssh_connection.setup()

        try:
            yield ssh_connection
        finally:
            ssh_connection.teardown()

    def get_namespace(self, node_id, du_id=None):
        """
        Get the namespace for a component on a node.

        :param int node_id: Node ID
        :param str component: Component
        :param int du_id: VDU ID
        :return: Namespace
        """
        if du_id is None:
            return self._tl_config_information_provider.get_cu_namespace(node_id)
        else:
            return self._tl_config_information_provider.get_vdu_namespace(node_id=node_id, vdu_id=du_id)

    def get_pods(self, node_id, du_id=None):
        """
        Get all pods of the given node.

        :param int node_id: Node ID of the node.
        :param int du_id: vDU ID of the vDU.
        :return: List of pod names.
        """
        pod_container_pairs = self._get_pod_container_pairs(node_id, du_id)
        pod_names = list({pod_name for pod_name, _ in pod_container_pairs})
        return pod_names

    def get_pod(self, node_id, component, du_id=None):
        """
        Get the pod name for a component in a namespace.

        :param int node_id: Node ID of the node where the component is deployed.
        :param str component: Pod name pattern to search for, e. g. "CPRT", "CPNB", ...
        :param int du_id: vDU ID of the vDU where the component is deployed.
            If set to 'None', the CU is used to retrieve pod names.
        :return: Pod name.
        """

        pod_container_pairs = self._get_pod_container_pairs(node_id, du_id)
        logger.info(pod_container_pairs)

        pod_component_names = list({pod_name for pod_name, _ in pod_container_pairs if component.lower() in pod_name})

        if len(pod_component_names) > 1:
            raise ValueError(f"More than one pod for [{component}]")

        elif len(pod_component_names) == 0:
            raise ValueError(f"No pod for component [{component}] pod_container_pairs: {pod_container_pairs}")

        return pod_component_names[0]

    def get_container(self, node_id, component, container_part, du_id=None):
        """
        Get the container name for a component and container_part in a namespace.

        For retrieving the container of a component, like i.e. CPRT, you use the component string for the arguments
        component and container_part, i.e.: get_container(node_id=0, component='CPNB', container_part='CPNB')

        :param int node_id: Node ID of the node where the component is deployed.
        :param str component: Pod name part to search for.
        :param str container_part: Container name part to search for.
        :param int du_id: vDU ID of the vDU where the component is deployed. If set to 'None', the cu is used.
        :return: Container name
        """

        pod_container_pairs = self._get_pod_container_pairs(node_id, du_id)

        container_component_names = list(
            {
                container
                for pod, container in pod_container_pairs
                if component.lower() in pod
                and container_part.lower() in container})

        if len(container_component_names) > 1:
            raise ValueError(
                f"More than one matches for container [{container_part}] "
                f"in component {component}: {container_component_names}")
        elif len(container_component_names) == 0:
            raise ValueError(f"No matches for container [{container_part}] in component {component}")
        return container_component_names[0]

    @cache_execution_results
    def _get_pod_container_pairs(self, node_id, du_id=None):

        with self.master_node_connection(node_id, du_id) as ssh_connection:
            namespace = self.get_namespace(node_id, du_id)

            kubectl_command = (
                rf"""kubectl get pods -n {namespace} -o json | """
                r"""jq -r '.items[]|"\(.metadata.name) \(.spec.containers[]|.name)"'""")

            logger.debug(f"Kubectl Command: {kubectl_command}")
            kubectl_output = ssh_connection.execute(kubectl_command)
            logger.debug(f"Kubectl output: {kubectl_output}")
            if not kubectl_output:
                raise AssertionError("No data retrieved from kubectl command!")

            return [pod_container.split() for pod_container in kubectl_output.splitlines()
                    if pod_container]
